def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The design has a two-cell outer margin, a color-4 frame, and a
    # diagonal-periodic field inside. Erased cells are marked with 0.
    background = Counter(grid[0]).most_common(1)[0][0]
    frame_values = [grid[2][c] for c in range(2, w) if grid[2][c] != 0]
    frame_values += [grid[r][2] for r in range(2, h) if grid[r][2] != 0]
    frame = Counter(frame_values).most_common(1)[0][0]

    diagonal_colors = {}
    for r in range(3, h):
        for c in range(3, w):
            value = grid[r][c]
            if value != 0:
                diagonal_colors.setdefault(r + c, Counter())[value] += 1
    diagonal_colors = {d: colors.most_common(1)[0][0]
                       for d, colors in diagonal_colors.items()}

    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = background
            elif r == 2 or c == 2:
                out[r][c] = frame
            else:
                out[r][c] = diagonal_colors[r + c]
    return out
